 <section class="card"><div class="card-heading"><div><div class="eyebrow">packed for the trail</div><h2 style="margin-top:4px">Satchel</h2></div><span style="font-size:17px">🎒</span></div><div class="bag-line"><div class="bag-item"><span class="item-icon">🔴</span>Capture pods</div><span class="bag-count" id="podCount">5</span></div><div class="bag-line"><div class="bag-item"><span class="item-icon" style="background:#eff3df">🍐</span>Glow pears</div><span class="bag-count" id="pearCount">3</span></div></section>
 <section class="card quest"><div class="card-heading" style="margin-bottom:10px"><div class="eyebrow">today's little quest</div><span style="font-size:15px">✨</span></div><div class="quest-line"><div class="quest-icon">🗺️</div><div class="quest-text"><strong>Meet the meadow folk</strong><p id="questText">Wander through the tall grass and say hello to a wild creature.</p></div></div></section></aside>
 </main></div>
 <script>
+const species=[
+{id:'mossling',name:'Mossling',type:'Leaf',colors:['#80bb74','#d5ecab'],shape:'round',emoji:'🌿',hp:40,atk:8,desc:'A tiny sprout with a brave heart.'},
+{id:'embercub',name:'Embercub',type:'Ember',colors:['#e78d62','#ffd18a'],shape:'fox',emoji:'🔥',hp:36,atk:10,desc:'A warm little spark with quick paws.'},
+{id:'brookfin',name:'Brookfin',type:'Tide',colors:['#64a8c0','#b6e8df'],shape:'fish',emoji:'💧',hp:44,atk:7,desc:'It hums softly beside clear streams.'},
+{id:'pufflet',name:'Pufflet',type:'Air',colors:['#d4b8df','#f3e5fb'],shape:'bird',emoji:'☁️',hp:34,atk:9,desc:'A feather-soft friend that loves breezes.'},
+{id:'dapplebug',name:'Dapplebug',type:'Leaf',colors:['#dfb35c','#ffebb0'],shape:'bug',emoji:'✨',hp:38,atk:8,desc:'Its bright spots glow at twilight.'},
+{id:'pebblit',name:'Pebblit',type:'Stone',colors:['#a8a99b','#e2dfc9'],shape:'round',emoji:'🪨',hp:48,atk:7,desc:'A pocket-sized rock with a big grin.'},
+{id:'bellbun',name:'Bellbun',type:'Bloom',colors:['#e28d9e','#ffd9d8'],shape:'bunny',emoji:'🌸',hp:38,atk:9,desc:'A gentle hopper with bell-shaped ears.'},
+{id:'glowmoth',name:'Glowmoth',type:'Air',colors:['#a99bd5','#eee1ff'],shape:'bug',emoji:'🌙',hp:35,atk:10,desc:'Its wings shimmer like a sleepy moon.'}
+];
+const $=s=>document.querySelector(s), world=$('#world'),ctx=world.getContext('2d');
+const state={started:false,team:[],active:0,pods:5,pears:3,catches:0,steps:0,grassSteps:0,player:{x:2,y:12,dir:'down'},battle:null,muted:false};
+function svgCreature(s,size=100){const [a,b]=s.colors;let extra='';if(s.shape==='fox')extra=`<path d="M29 43 23 14 43 32M59 32 78 13 73 46" fill="${a}" stroke="#375d4a" stroke-width="3" stroke-linejoin="round"/><path d="m28 22 9 13M73 22 64 35" stroke="${b}" stroke-width="5"/>`;if(s.shape==='bunny')extra=`<path d="M37 39Q19 2 34 8Q46 10 46 37M57 37Q64 5 77 13Q85 22 64 43" fill="${a}" stroke="#375d4a" stroke-width="3"/><path d="M34 14Q41 21 42 32M75 19Q71 26 66 35" stroke="${b}" stroke-width="5"/>`;if(s.shape==='bird')extra=`<path d="M31 43Q13 30 18 18Q38 22 45 39M61 40Q73 22 86 27Q81 45 66 51" fill="${b}" stroke="#375d4a" stroke-width="3"/><path d="m70 52 16 6-16 7" fill="#e9ad54"/>`;if(s.shape==='fish')extra=`<path d="M31 51 15 34 15 68 33 60" fill="${b}" stroke="#375d4a" stroke-width="3"/><path d="M47 40Q39 29 47 24Q57 28 54 41" fill="${b}" stroke="#375d4a" stroke-width="2"/><path d="M62 50q12 8 0 16" fill="none" stroke="#4d8793" stroke-width="3"/>`;if(s.shape==='bug')extra=`<path d="M44 38Q17 10 17 42Q22 57 43 55M57 39Q83 10 83 42Q77 57 58 55" fill="${b}" stroke="#375d4a" stroke-width="3"/><path d="M46 34 37 22M56 34 66 22" stroke="#375d4a" stroke-width="3" stroke-linecap="round"/><circle cx="30" cy="39" r="3" fill="${a}"/><circle cx="70" cy="39" r="3" fill="${a}"/>`;if(s.id==='mossling')extra+=`<path d="M48 33Q41 14 30 19Q31 34 47 39M53 32Q57 11 72 17Q70 32 55 39" fill="#98c97a" stroke="#527d55" stroke-width="2"/><path d="M31 56q-10 5-12-3" fill="none" stroke="${a}" stroke-width="8" stroke-linecap="round"/>`;if(s.id==='embercub')extra+=`<path d="M68 61q22 0 15-17q-2-9-10-9q8 11 0 13q-2-10-9-13q5 14-3 17" fill="#f2a64e" stroke="#bd7051" stroke-width="2"/>`;if(s.id==='brookfin')extra+=`<path d="M47 32Q51 17 58 28L55 36M39 64Q32 78 51 75" fill="none" stroke="#478fa7" stroke-width="3"/>`;return `<svg viewBox="0 0 100 100" role="img" aria-label="${s.name}" xmlns="http://www.w3.org/2000/svg"><ellipse cx="50" cy="87" rx="26" ry="6" fill="#55724b" opacity=".15"/>${extra}<ellipse cx="51" cy="57" rx="27" ry="26" fill="${a}" stroke="#375d4a" stroke-width="3"/><ellipse cx="50" cy="69" rx="17" ry="10" fill="${b}"/><ellipse cx="42" cy="54" rx="3.5" ry="5" fill="#243f3d"/><ellipse cx="60" cy="54" rx="3.5" ry="5" fill="#243f3d"/><circle cx="43" cy="52" r="1.2" fill="white"/><circle cx="61" cy="52" r="1.2" fill="white"/><path d="M48 64q3 3 6 0" fill="none" stroke="#654d46" stroke-width="2" stroke-linecap="round"/><circle cx="33" cy="62" r="3" fill="#ee9d8d"/><circle cx="68" cy="62" r="3" fill="#ee9d8d"/><path d="M34 77q-3 4-8 2M65 77q3 4 8 2" fill="none" stroke="#375d4a" stroke-width="3" stroke-linecap="round"/></svg>`}
+const starterIds=['mossling','embercub','brookfin'];function getSpecies(id){return species.find(s=>s.id===id)||species[0]};function makeCreature(s,level=1){return{id:s.id,name:s.name,level,maxHp:s.hp+level*3,hp:s.hp+level*3,xp:0,atk:s.atk+level*2}}
+const W=900,H=565,T=36,COLS=25,ROWS=15;const player={x:2,y:12};
+const pathTiles=new Set();function addPath(x1,y1,x2,y2){let x=x1,y=y1;for(let i=0;i<80;i++){pathTiles.add(`${x},${y}`);if(x===x2&&y===y2)break;if(x!==x2)x+=Math.sign(x2-x);else if(y!==y2)y+=Math.sign(y2-y)}}addPath(2,12,11,9);addPath(11,9,12,7);addPath(12,9,19,9);addPath(12,9,12,3);addPath(19,9,21,12);addPath(2,12,1,14);
+const grassPatches=[{x:3,y:3,w:5,h:3},{x:8,y:11,w:4,h:3},{x:17,y:11,w:5,h:3},{x:18,y:4,w:4,h:3},{x:5,y:8,w:3,h:2}];function isTall(x,y){return grassPatches.some(p=>x>=p.x&&x<p.x+p.w&&y>=p.y&&y<p.y+p.h)}
+const trees=[[1,1],[3,1],[6,1],[10,1],[14,1],[20,1],[23,1],[1,5],[10,4],[14,5],[23,7],[1,9],[3,10],[14,11],[15,12],[23,12],[6,14],[11,14],[18,14],[23,14],[8,6],[9,6],[15,8],[16,8]];
+function pondAt(x,y){return((x-20.5)/3.2)**2+((y-5.5)/2.2)**2<1}
+function blocked(x,y){return x<0||y<0||x>=COLS||y>=ROWS||trees.some(([tx,ty])=>tx===x&&ty===y)||pondAt(x,y)}
+function drawWorld(){ctx.clearRect(0,0,W,H);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){let n=(x*17+y*31+x*y*7)%7;ctx.fillStyle=['#a9d68f','#aed993','#a6d18b','#b0d993','#a5d18a','#acd68e','#aad48d'][n];ctx.fillRect(x*T,y*T,T,T);ctx.fillStyle='#87bc7770';ctx.fillRect(x*T,y*T+T-2,T,2);if(pathTiles.has(`${x},${y}`)){ctx.fillStyle=['#d9c99c','#d4c393','#dfd0a6'][(x+y)%3];ctx.fillRect(x*T,y*T,T,T);ctx.fillStyle='#bea97655';ctx.fillRect(x*T,y*T+T-2,T,2);if((x*3+y)%5===0){ctx.fillStyle='#b9a87577';ctx.fillRect(x*T+9,y*T+14,3,2)}}}
+// water pond
+ctx.save();ctx.fillStyle='#75c1c3';ctx.beginPath();ctx.ellipse(20.5*T+18,5.5*T+17,3.2*T,2.2*T,.08,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e3f4d2';ctx.lineWidth=7;ctx.stroke();ctx.restore();for(let i=0;i<7;i++){let x=(18.4+(i*7%25)*.16)*T,y=(4.5+(i*13%19)*.12)*T;ctx.strokeStyle='#b5e5d7';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+10,y-4,x+21,y);ctx.stroke()}
+// small footbridge
+ctx.fillStyle='#aa8058';ctx.fillRect(18*T,5*T,2*T,22);for(let i=0;i<4;i++){ctx.fillStyle=i%2?'#d1a26d':'#c3915e';ctx.fillRect(18*T+i*18,5*T,13,22)}
+// tall grass
+for(const p of grassPatches){for(let y=p.y;y<p.y+p.h;y++)for(let x=p.x;x<p.x+p.w;x++){ctx.fillStyle=['#7ab66d','#82bc6e','#76b469'][(x+y)%3];ctx.fillRect(x*T,y*T,T,T);for(let j=0;j<5;j++){let bx=x*T+5+((j*11+x*7+y*13)%26),by=y*T+29-((j*7+x*3)%11);ctx.strokeStyle=['#4f965d','#5ca367','#438d57'][j%3];ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(bx,by);ctx.quadraticCurveTo(bx-4,by-9,bx-2,by-15);ctx.moveTo(bx+1,by);ctx.quadraticCurveTo(bx+6,by-7,bx+4,by-13);ctx.stroke()}if((x+y)%4===0){ctx.fillStyle='#f8e98e';ctx.beginPath();ctx.arc(x*T+18,y*T+16,3,0,7);ctx.fill()}}}
+// decorative flowers and stones
+for(let i=0;i<44;i++){let x=(i*37+21)%COLS,y=(i*19+2)%ROWS;if(pathTiles.has(`${x},${y}`)||trees.some(t=>t[0]===x&&t[1]===y)||isTall(x,y)||pondAt(x,y))continue;let px=x*T+((i*13)%28)+4,py=y*T+((i*17)%27)+5;ctx.fillStyle=['#f8e8a2','#f1b6a5','#fff5d5','#d7c6ed'][i%4];ctx.beginPath();ctx.arc(px,py,2.4,0,7);ctx.fill();ctx.fillStyle='#e6ac65';ctx.beginPath();ctx.arc(px,py,1,0,7);ctx.fill()}
+// trees on foreground
+for(const [x,y] of trees){let px=x*T+18,py=y*T+19;ctx.fillStyle='#8c6247';ctx.fillRect(px-5,py+5,10,20);ctx.fillStyle='#5e9d65';ctx.beginPath();ctx.arc(px,py-4,19,0,7);ctx.fill();ctx.fillStyle='#70af70';ctx.beginPath();ctx.arc(px-8,py-10,13,0,7);ctx.fill();ctx.fillStyle='#8ac27b';ctx.beginPath();ctx.arc(px+7,py-11,10,0,7);ctx.fill();ctx.fillStyle='#ffffff2a';ctx.beginPath();ctx.arc(px-6,py-14,4,0,7);ctx.fill()}
+// cottage
+ctx.fillStyle='#f7e6be';ctx.fillRect(11*T+3,7*T+17,62,40);ctx.fillStyle='#bf8462';ctx.beginPath();ctx.moveTo(11*T-1,7*T+20);ctx.lineTo(12*T+18,7*T-8);ctx.lineTo(13*T+36,7*T+20);ctx.closePath();ctx.fill();ctx.fillStyle='#93b8a0';ctx.fillRect(11*T+12,7*T+27,13,13);ctx.fillRect(11*T+43,7*T+27,13,13);ctx.fillStyle='#d5b87f';ctx.fillRect(11*T+30,7*T+37,12,20);ctx.fillStyle='#fff4c6';ctx.font='10px sans-serif';ctx.fillText('✿',11*T+33,7*T+53);
+// player shadow and sprite
+const px=player.x*T+18,py=player.y*T+18;ctx.fillStyle='#416b4b55';ctx.beginPath();ctx.ellipse(px,py+11,12,5,0,0,7);ctx.fill();ctx.fillStyle='#f2bd85';ctx.beginPath();ctx.arc(px,py-5,8,0,7);ctx.fill();ctx.fillStyle='#395f4e';ctx.beginPath();ctx.arc(px,py-9,9,Math.PI,0);ctx.lineTo(px+9,py-5);ctx.lineTo(px-9,py-5);ctx.fill();ctx.fillStyle='#e88465';ctx.fillRect(px-7,py+3,14,12);ctx.fillStyle='#fff2d6';ctx.fillRect(px-5,py+14,4,4);ctx.fillRect(px+2,py+14,4,4);ctx.fillStyle='#3d5f4e';ctx.fillRect(px-10,py+3,3,8);ctx.fillRect(px+7,py+3,3,8);ctx.fillStyle='#263e39';ctx.fillRect(px-3,py-5,2,2);ctx.fillRect(px+3,py-5,2,2);
+}

input.newString:
ctx.fillStyle='#263e39';ctx.fillRect(px-3,py-5,2,2);ctx.fillRect(px+3,py-5,2,2);
}
function renderRoster(){const root=$('#roster');if(!state.team.length){root.innerHTML='<div class="roster-empty">Your trail team is waiting.<br>Choose a companion to begin!</div>';return}root.innerHTML=state.team.map((c,i)=>{const s=getSpecies(c.id);return `<div class="creature-row ${i===state.active?'active':''}" data-index="${i}" title="Make ${c.name} your trail companion"><div class="creature-thumb">${svgCreature(s)}</div><div class="creature-info"><strong>${c.name}</strong><small>${s.type} friend</small><div class="tiny-hp"><span style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></span></div></div><span class="row-level">Lv.${c.level}</span></div>`}).join('');root.querySelectorAll('.creature-row').forEach(el=>el.onclick=()=>{if(state.battle)return;state.active=Number(el.dataset.index);renderRoster();toast(`${state.team[state.active].name} is leading the way!`)})}
function renderStarter(){const box=$('#starterOptions');box.innerHTML=starterIds.map(id=>{const s=getSpecies(id);return `<button class="starter-choice" data-id="${id}"><div class="starter-art">${svgCreature(s)}</div><strong>${s.name}</strong><small>${s.desc}</small><span class="type-tag">${s.type} type</span></button>`}).join('');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{const c=makeCreature(getSpecies(b.dataset.id));state.team.push(c);state.started=true;$('#starterScreen').classList.remove('show');renderRoster();updateHUD();toast(`${c.name} joined your trail team!`);drawWorld()})}
function updateHUD(){$('#podCount').textContent=state.pods;$('#pearCount').textContent=state.pears;$('#dexCount').textContent=`${state.catches} caught`;$('#questText').textContent=state.catches?`Lovely! You have befriended ${state.catches} meadow ${state.catches===1?'creature':'creatures'}. Keep exploring to meet more.`:'Wander through the tall grass and say hello to a wild creature.'}
let toastTimer;function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function move(dir){if(!state.started||state.battle)return;const d={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir];if(!d)return;state.player.dir=dir;const nx=player.x+d[0],ny=player.y+d[1];if(blocked(nx,ny)){drawWorld();return}player.x=nx;player.y=ny;state.steps++;if(isTall(nx,ny)){state.grassSteps++;if(state.grassSteps>1&&Math.random()<.19){drawWorld();startBattle();return}}else state.grassSteps=0;$('#sceneHint').textContent=isTall(nx,ny)?'The grass rustles nearby…':'WASD or arrow keys to explore';drawWorld()}
let lastStep=0;window.addEventListener('keydown',e=>{const keys={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};if(keys[e.key]){e.preventDefault();const now=Date.now();if(now-lastStep>115){lastStep=now;move(keys[e.key])}}});document.querySelectorAll('.dpad button').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();move(b.dataset.dir)})});
function randomWild(){const pool=species.filter(s=>!starterIds.includes(s.id));const s=Math.random()<.27?getSpecies(starterIds[Math.floor(Math.random()*3)]):pool[Math.floor(Math.random()*pool.length)];const c=makeCreature(s,1+Math.floor(Math.random()*2));c.hp=c.maxHp;return c}
function startBattle(){if(state.battle||!state.team.length)return;const foe=randomWild();state.battle={foe,turn:0,log:`A wild ${foe.name} wandered over!`,busy:false};$('#battleLayer').classList.add('show');$('#sceneHint').textContent='A new friend is just a pod away!';renderBattle();}
function battleCard(c,foe=false){return `<span class="battle-level">Lv. ${c.level}</span><div class="battle-name">${c.name}</div><div class="hp-line"><span style="width:${Math.max(0,c.hp/c.maxHp*100)}%"></span></div><div class="hp-numbers">${Math.max(0,c.hp)} / ${c.maxHp} HP</div>`}
function renderBattle(){if(!state.battle)return;let c=state.team[state.active],f=state.battle.foe;$('#playerBattleCard').innerHTML=battleCard(c);$('#foeBattleCard').innerHTML=battleCard(f,true);$('#foeArt').innerHTML=svgCreature(getSpecies(f.id));$('#playerArt').innerHTML=svgCreature(getSpecies(c.id));$('#battleLog').textContent=state.battle.log;const controls=$('#battleControls');if(state.battle.busy){controls.innerHTML='<span class="action-label">One moment…</span>';return}controls.innerHTML=`<span class="action-label">Your move</span><button class="action-btn primary" data-action="tackle">🌱 Tackle</button><button class="action-btn primary" data-action="special">✨ ${getSpecies(c.id).type} burst</button><button class="action-btn capture" data-action="capture" ${state.pods<1?'disabled':''}>🔴 Pod · ${state.pods}</button><button class="action-btn" data-action="heal" ${state.pears<1||c.hp>=c.maxHp?'disabled':''}>🍐 Pear · ${state.pears}</button><button class="action-btn" data-action="run">↗ Go home</button>`;controls.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>battleAction(b.dataset.action))}
function endBattle(text){if(!state.battle)return;state.battle.log=text;state.battle.busy=true;renderBattle();setTimeout(()=>{$('#battleLayer').classList.remove('show');state.battle=null;$('#sceneHint').textContent='WASD or arrow keys to explore';updateHUD();renderRoster()},1250)}
function battleAction(action){const b=state.battle;if(!b||b.busy)return;const c=state.team[state.active],f=b.foe;if(action==='run'){endBattle('You waved goodbye and headed back to the trail.');return}if(action==='heal'){if(state.pears<=0||c.hp>=c.maxHp)return;state.pears--;const amount=Math.min(22,c.maxHp-c.hp);c.hp+=amount;b.log=`A glow pear restored ${c.name} by ${amount} HP!`;renderBattle();setTimeout(enemyTurn,700);updateHUD();return}if(action==='capture'){if(state.pods<=0)return;state.pods--;const chance=.27+.61*(1-f.hp/f.maxHp);if(Math.random()<chance){const caught={...f,hp:f.maxHp};state.team.push(caught);state.catches++;b.log=`Click! ${f.name} is happy to join your trail team!`;renderBattle();updateHUD();renderRoster();endBattle(`${f.name} joined your trail team!`);return}else{b.log=`Oh! ${f.name} wriggled out of the capture pod!`;renderBattle();setTimeout(enemyTurn,700);updateHUD();return}}
const special=action==='special';const damage=Math.max(3,Math.floor(c.atk*(special?1.38:.93)+Math.random()*4));f.hp=Math.max(0,f.hp-damage);b.log=`${c.name} used ${special?getSpecies(c.id).type+' burst':'Tackle'}! ${damage} damage!`;b.turn++;if(f.hp<=0){c.xp+=12;c.level+=c.xp>=20?1:0;c.xp=c.xp>=20?c.xp-20:c.xp;c.maxHp+=c.level>1?3:0;c.hp=Math.min(c.maxHp,c.hp+8);b.log=`${f.name} skipped away. ${c.name} gained 12 trail XP!`;renderBattle();renderRoster();endBattle(b.log);return}renderBattle();setTimeout(enemyTurn,700)}
function enemyTurn(){const b=state.battle;if(!b)return;const c=state.team[state.active],f=b.foe;if(c.hp<=0){const next=state.team.findIndex(x=>x.hp>0);if(next>=0){state.active=next;b.log=`${c.name} needs a breather. ${state.team[next].name}, you're up!`;renderBattle();renderRoster();return}else{state.team.forEach(x=>x.hp=x.maxHp);state.active=0;b.log='Everyone is safe and sound after a little rest at camp.';renderBattle();endBattle(b.log);return}}const damage=Math.max(3,Math.floor(f.atk*.65+Math.random()*4));c.hp=Math.max(0,c.hp-damage);b.log=`${f.name} gave ${c.name} a gentle bonk for ${damage}!`;renderBattle();renderRoster()}

