58: const pathTiles=new Set();function addPath(x1,y1,x2,y2){let x=x1,y=y1;for(let i=0;i<80;i++){pathTiles.add(`${x},${y}`);if(x===x2&&y===y2)break;if(x!==x2)x+=Math.sign(x2-x);else if(y!==y2)y+=Math.sign(y2-y)}}addPath(2,12,11,9);addPath(11,9,12,7);addPath(12,9,19,9);addPath(12,9,12,3);addPath(19,9,21,12);addPath(2,12,1,14);
