60: function isWater(x,y){return state.biome==='tide'&&((x-20.5)/4.3)**2+((y-5.5)/3.3)**2<1}
61: function biomeGrass(x,y){return state.biome==='meadow'?isTall(x,y):state.biome==='tide'?((x-7)/3.4)**2+((y-7)/2.5)**2<1:state.biome==='ember'?((x-17)/3.6)**2+((y-9)/2.6)**2<1:((x-5)/3.5)**2+((y-5)/2.8)**2<1}
