64: function blocked(x,y){if(x<0||y<0||x>=COLS||y>=ROWS)return true;if(state.biome==='meadow')return trees.some(([tx,ty])=>tx===x&&ty===y)||pondAt(x,y);if(state.biome==='tide')return isWater(x,y);if(state.biome==='ember')return (x-12)**2+(y-4)**2<4||((x-21)**2+(y-11)**2<3);return (x===12&&y===7)||(x===12&&y===8)}
65: function drawWorld(){const biome=biomeData[state.biome];ctx.clearRect(0,0,W,H);for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){let n=(x*17+y*31+x*y*7)%biome.colors.length;ctx.fillStyle=biome.colors[n];ctx.fillRect(x*T,y*T,T,T);ctx.fillStyle='#527b5a35';ctx.fillRect(x*T,y*T+T-2,T,2);if(pathTiles.has(`${x},${y}`)){ctx.fillStyle=state.biome==='tide'?'#d9d0ad':state.biome==='ember'?'#b98b6f':state.biome==='moon'?'#b3b0a2':['#d9c99c','#d4c393','#dfd0a6'][(x+y)%3];ctx.fillRect(x*T,y*T,T,T);ctx.fillStyle='#635e4d33';ctx.fillRect(x*T,y*T+T-2,T,2);if((x*3+y)%5===0){ctx.fillStyle='#b9a87577';ctx.fillRect(x*T+9,y*T+14,3,2)}}if(biomeGrass(x,y)){ctx.fillStyle=state.biome==='tide'?'#51a99d':state.biome==='ember'?'#b67852':state.biome==='moon'?'#627d6b':['#7ab66d','#82bc6e','#76b469'][(x+y)%3];ctx.fillRect(x*T,y*T,T,T);for(let j=0;j<4;j++){ctx.strokeStyle=state.biome==='tide'?'#e1dd9b':state.biome==='ember'?'#edb265':state.biome==='moon'?'#a1cfaa':'#4f965d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x*T+6+j*7,y*T+30);ctx.quadraticCurveTo(x*T+3+j*8,y*T+16,x*T+8+j*7,y*T+8);ctx.stroke()}}}
