const starterIds=['mossling','embercub','brookfin'];function getSpecies(id){return species.find(s=>s.id===id)||species[0]};function makeCreature(s,level=1){return{id:s.id,name:s.name,level,maxHp:s.hp+level*3,hp:s.hp+level*3,xp:0,atk:s.atk+level*2}}function markDiscovered(id){if(!state.discovered[id]){state.discovered[id]=true;updateHUD()}}function renderDex(){const seen=Object.keys(state.discovered).length;$('#dexSummary').textContent=`${seen} of ${species.length} species discovered · ${Object.keys(state.caught).length} befriended`;$('#dexGrid').innerHTML=species.map((s,i)=>{const known=!!state.discovered[s.id],owned=!!state.caught[s.id];return `<article class="dex-entry ${known?'':'unknown'}"><div class="dex-entry-art">${known?svgCreature(s):`<span style="font-size:30px">?</span>`}</div><strong>${known?s.name:`Unknown #${String(i+1).padStart(2,'0')}`}</strong><small>${known?`${s.type} · ${s.desc}`:'Not yet discovered'}</small><span class="dex-status">${owned?'Befriended':known?'Seen':'Unknown'}</span></article>`}).join('')}function evolveCreature(c){const old=getSpecies(c.id);if(!old.evolvesTo||c.level<3)return false;const evolved=getSpecies(old.evolvesTo),ratio=c.maxHp?c.hp/c.maxHp:1;c.id=evolved.id;c.name=evolved.name;c.maxHp=Math.round(c.maxHp*1.35);c.hp=Math.max(1,Math.round(c.maxHp*ratio));c.atk=Math.round(c.atk*1.3);state.discovered[c.id]=true;state.caught[c.id]=true;return true}
