const fs=require('fs');
const html=fs.readFileSync('index.html','utf8');
const match=html.match(/const species=(\[[\s\S]*?\]);/);
if(!match) throw new Error('Species data not found');
const species=Function(`return ${match[1]}`)();
const ids=new Set(species.map(s=>s.id));
const broken=species.filter(s=>s.evolvesTo&&!ids.has(s.evolvesTo));
if(species.length!==19||broken.length) throw new Error(`Species=${species.length}; invalid evolution targets=${broken.map(s=>s.evolvesTo)}`);
console.log(`Validated ${species.length} species; evolution targets resolve.`);
